1	// THE TERMINAL TRANSITION, IN CODE (#892; tasks-dispatch DESIGN §6.5, §15.18).
2	// A work-item session ends by performing five ordered side effects — comment,
3	// drop `task:agent`, add the outcome label, carry the execution record, close
4	// with the right state reason — on the item it holds, and nothing else: a
5	// converge never writes to another work item (§15.19, reversed by §15.31 /
6	// #1373). Releasing a dependent a close may have freed is the scheduler run's
7	// job alone. Asking a session to perform these effects from prose is asking for
8	// it at the moment its context is fullest and the remaining work looks like
9	// formality; both of the first two live agentic runs got part of it wrong,
10	// silently, in different ways.
11	//
12	// The split is the same one the executor already draws: THE SESSION SUPPLIES THE
13	// JUDGMENT — which outcome, and the prose of what happened — and the CODE
14	// performs the transition. A session that stops early now leaves an item that is
15	// visibly unconverged, rather than one that looks finished and is not.
16	//
17	// Usage:
18	//   node converge-item.mjs --issue <n> --outcome <done|approval|action|decision|failure>
19	//                          --summary <text> [--pr <n>]
20	
21	import { pathToFileURL } from 'node:url';
22	import { renderTaskExec } from '../run-record.mjs';
23	import {
24	  AGENT, TASK_DONE, STATUS_RUNNING_AGENT, isStatus, isWorkItemTitle, machineBlockOf,
25	  NEEDS_HUMAN_ACTION, NEEDS_HUMAN_APPROVAL, NEEDS_HUMAN_DECISION, NEEDS_HUMAN_FAILURE,
26	  QUEUED_LABEL, IN_REVIEW_LABEL,
27	  parseWorkItemTitle, parseWorkItemBody, spellingsOf, labelNames,
28	} from './work-item.mjs';
29	
30	// What a session may claim, and what each one means for the item. `record` is the
31	// execution-record status, and `null` means no record: an approval park is a run
32	// that SUCCEEDED and left a PR, which the record vocabulary has no word for, and
33	// a fifth status would be stored data every decoder in the fleet must learn.
34	export const OUTCOMES = Object.freeze({
35	  done: { label: TASK_DONE, closes: true, stateReason: 'completed', record: 'success' },
36	  approval: { label: NEEDS_HUMAN_APPROVAL, closes: false, record: null },
37	  action: { label: NEEDS_HUMAN_ACTION, closes: false, record: 'failed' },
38	  decision: { label: NEEDS_HUMAN_DECISION, closes: false, record: 'failed' },
39	  failure: { label: NEEDS_HUMAN_FAILURE, closes: false, record: 'failed' },
40	});
41	
42	export function parseArgs(argv) {
43	  const args = {};
44	  for (let n = 0; n < argv.length; n += 1) {
45	    const m = /^--([a-z-]+)$/.exec(argv[n]);
46	    if (m) { args[m[1]] = argv[n + 1] ?? ''; n += 1; }
47	  }
48	  const issue = Number(args.issue);
49	  if (!Number.isInteger(issue) || issue <= 0) return { error: '--issue must be the work item\'s issue number' };
50	  if (!OUTCOMES[args.outcome]) {
51	    return { error: `--outcome must be one of ${Object.keys(OUTCOMES).join(', ')}, got ${JSON.stringify(args.outcome ?? null)}` };
52	  }
53	  if (!String(args.summary ?? '').trim()) return { error: '--summary must say what happened; it is the item\'s only durable account' };
54	  if (args.outcome === 'approval' && !args.pr) {
55	    return { error: '--pr must name the pull request an approval park is waiting on — a park nobody can act on is not a park' };
56	  }
57	  return { issue, outcome: args.outcome, summary: args.summary, pr: args.pr ? Number(args.pr) : null };
58	}
59	
60	// Why an item may NOT be converged by this call. Refusing loudly beats writing a
61	// terminal state onto the wrong issue: this runs from a session, whose whole
62	// notion of which item it holds came from an untrusted fire payload.
63	export function refusal(item, issue) {
64	  if (!item) return `#${issue} could not be read`;
65	  // A marked issue IS its own item (DESIGN §16.1), so the title test cannot be the
66	  // membership test any more: what says this is one is the machine block adoption
67	  // wrote — never the body's first line, which on a marked issue is a person's prose.
68	  if (!parseWorkItemTitle(item.title ?? '') && machineBlockOf(item.body ?? '') === null) {
69	    return `#${issue} is not a Claudinite work item`;
70	  }
71	  if (item.state !== 'open') return `#${issue} is already closed — it was converged once already`;
72	  if (!isStatus(item, STATUS_RUNNING_AGENT)) {
73	    return `#${issue} is not with an agent (\`${AGENT}\`) — this session does not hold it, so it is not this session's to converge`;
74	  }
75	  return null;
76	}
77	
78	// The record line for this item, or null where the vocabulary has no true answer.
79	export const recordLine = (item, status) => {
80	  const parsed = parseWorkItemTitle(item.title);
81	  return status && parsed
82	    ? renderTaskExec({ pack: parsed.pack, task: parsed.task, slotId: `#${item.number}`, status })
83	    : null;
84	};
85	
86	// The comment one converge writes: the session's account, then the record, so a
87	// reader and a parser both find what they came for in one place.
88	export function convergeComment(item, { summary, pr, record }) {
89	  const rec = recordLine(item, record);
90	  const line = rec ? `\n\n\`\`\`\n${rec}\n\`\`\`` : '';
91	  const waiting = pr ? `\n\nWaiting on a person: merge or close #${pr}, then close this item.` : '';
92	  return `${summary.trim()}${waiting}${line}`;
93	}
94	
95	// THE TRANSITION AS DATA (#1374). The side effects were a straight line of
96	// `await api.…` calls, which silently made REST the only way to perform them —
97	// and the sessions `invoke.mjs` hands work to have no REST route to their own
98	// repository, so the last step of every agentic run was the one step that
99	// environment could not take.
100	//
101	// So the sequence is planned as OPS and executed by whoever can. The planner is
102	// the single source of what a convergence IS; the executors differ only in
103	// transport. The session still supplies nothing but the judgment.
104	//
105	// Removes are granular and unconditional — every spelling of the status being
106	// left, not only the ones this snapshot shows (apply-status.mjs's rule: a member's
107	// items outlive its converges, so an item may wear an older engine's spelling).
108	export function convergeOps(item, plan) {
109	  const spec = OUTCOMES[plan.outcome];
110	  const ops = [{ kind: 'comment', issue: item.number, body: convergeComment(item, { ...plan, record: spec.record }) }];
111	
112	  // The record goes to BOTH sinks, and neither is redundant: the comment above is
113	  // the durable one (Actions logs expire, the item does not), while this printed
114	  // copy lands in the session transcript, which is what the usage fold reads for
115	  // the task-status census.
116	  const rec = recordLine(item, spec.record);
117	  if (rec) ops.push({ kind: 'record', line: rec });
118	
119	  for (const label of spellingsOf(STATUS_RUNNING_AGENT)) {
120	    ops.push({ kind: 'removeLabel', issue: item.number, name: label });
121	  }
122	  // ONE label, on both paths: the outcome IS the status. A park in particular is
123	  // never a pair, so nothing can be half-applied (#1385).
124	  ops.push({ kind: 'addLabel', issue: item.number, name: spec.label });
125	
126	  if (spec.closes) {
127	    // A MARKED ISSUE IS NOT THE SESSION'S TO CLOSE (§16.1, §16.5): the terminal
128	    // status stands on the open issue, and whether the issue itself is finished
129	    // belongs to the person who opened it.
130	    if (isWorkItemTitle(item.title ?? '')) ops.push({ kind: 'close', issue: item.number, stateReason: spec.stateReason });
131	    return ops;
132	  }
133	
134	  // A REQUEST ITEM WRITES BACK TO ITS ISSUE, on the one end that is its business
135	  // (§16.5). Only the approval park: a failure deliberately writes nothing and
136	  // leaves `claude-queued` standing, because re-arming work that writes code is a
137	  // person's decision and that standing label is what stops the next scheduler run
138	  // queueing a second run of the same request. Only a LEGACY shadow item writes
139	  // back to a different issue.
140	  const { request } = parseWorkItemBody(item.body ?? '');
141	  if (request && request !== item.number && plan.outcome === 'approval') {
142	    ops.push({ kind: 'comment', issue: request, body: `A pull request for this is open and waiting on you: #${plan.pr}. Merge or close it.` });
143	    ops.push({ kind: 'removeLabel', issue: request, name: QUEUED_LABEL });
144	    ops.push({ kind: 'addLabel', issue: request, name: IN_REVIEW_LABEL });
145	  }
146	  return ops;
147	}
148	
149	// THE REST EXECUTOR — what an Actions run does, unchanged in behaviour.
150	export async function convergeItem(api, gh, repo, plan, { log = console.log } = {}) {
151	  const item = await api.readIssue(gh, repo, plan.issue);
152	  const no = refusal(item, plan.issue);
153	  if (no) return { ok: false, error: no };
154	
155	  let closed = false;
156	  for (const op of convergeOps(item, plan)) {
157	    if (op.kind === 'comment') await api.comment(gh, repo, op.issue, op.body);
158	    else if (op.kind === 'record') log(op.line);
159	    else if (op.kind === 'removeLabel') await api.removeLabel(gh, repo, op.issue, op.name);
160	    else if (op.kind === 'addLabel') await api.addLabel(gh, repo, op.issue, op.name);
161	    else if (op.kind === 'close') { await api.closeIssue(gh, repo, op.issue, op.stateReason); closed = true; }
162	  }
163	  const { request } = parseWorkItemBody(item.body ?? '');
164	  return { ok: true, closed, request: request ?? null };
165	}
166	
167	// THE SESSION EXECUTOR'S SCRIPT. Same ops, addressed to the GitHub tools a session
168	// does have. Two differences forced by that surface, both handled here rather than
169	// left to the session to work out:
170	//
171	//  - THERE IS NO GRANULAR LABEL WRITE. `issue_write` replaces the whole set, so the
172	//    granular removes and adds are folded into the FINAL set here, computed from the
173	//    labels this item was read with. Everything not a status label is carried through.
174	//  - THE RECORD IS PRINTED BY THE SESSION, which is where it has to be anyway: the
175	//    usage fold reads the census out of the session transcript.
176	export function sessionScript(item, plan, repo) {
177	  const [owner, name] = String(repo).split('/');
178	  const lines = [];
179	  let n = 0;
180	  const step = (s) => { n += 1; lines.push(`${n}. ${s}`); };
181	
182	  // The item's own label set can be computed exactly, because the item was read
183	  // with its labels. Any OTHER issue's cannot — so that one is emitted as a
184	  // read-modify-write naming only the change, and never as a computed set, which
185	  // would silently drop every label this process never saw.
186	  const own = new Set(labelNames(item));
187	  const foreign = [];
188	
189	  for (const op of convergeOps(item, plan)) {
190	    if (op.kind === 'comment') {
191	      step(`\`add_issue_comment\` — owner \`${owner}\`, repo \`${name}\`, issue_number \`${op.issue}\`, body exactly:\n\n<<<BODY\n${op.body}\n>>>END\n`);
192	    } else if (op.kind === 'record') {
193	      step(`Output this line, on its own, in your reply. Nothing else emits it, and the usage census is read from your transcript:\n\n    ${op.line}\n`);
194	    } else if (op.kind === 'removeLabel' || op.kind === 'addLabel') {
195	      if (op.issue === item.number) {
196	        if (op.kind === 'removeLabel') own.delete(op.name); else own.add(op.name);
197	      } else {
198	        foreign.push(op);
199	      }
200	    } else if (op.kind === 'close') {
201	      step(`\`issue_write\` — method \`update\`, owner \`${owner}\`, repo \`${name}\`, issue_number \`${op.issue}\`,`
202	        + ` labels \`${JSON.stringify([...own])}\`, state \`closed\`, state_reason \`${op.stateReason}\``);
203	      own.clear();
204	    }
205	  }
206	  // A park never closed, so its label write is still owed.
207	  if (own.size) {
208	    step(`\`issue_write\` — method \`update\`, owner \`${owner}\`, repo \`${name}\`, issue_number \`${item.number}\`,`
209	      + ` labels \`${JSON.stringify([...own])}\``);
210	  }
211	  for (const op of foreign) {
212	    step(`On #${op.issue}: ${op.kind === 'addLabel' ? 'ADD' : 'REMOVE'} the label \`${op.name}\`.`
213	      + ` Read that issue's current labels first and write them back with only this one change —`
214	      + ` \`issue_write\` replaces the whole set, and this process never saw the rest.`);
215	  }
216	  return lines.join('\n');
217	}
